pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with excessive residual space
    if post_residual < 10 {
        score += 5.0 * ((10 - post_residual) as f64).powi(2);
    }

    // Reward using bins that are almost full
    if bin_residual <= 10 {
        score -= 3.0 * (bin_capacity - bin_residual) as f64;
    }

    // Penalize not fitting the next item in any open bin
    if fitting_bins_count == 0 {
        score += 2.0 * next_item_size as f64;
    }

    // Reward using bins that can fit the next item
    if fitting_bins_count > 0 {
        score -= 1.5 * (next_item_size as f64 - bin_residual) as f64;
    }

    // Penalize opening a new bin when there are open bins with some capacity left
    if open_bins_count > 1 && post_residual >= item_size {
        score += 3.0 * ((open_bins_count - 1) as f64).powi(2);
    }

    // Reward using bins that minimize the mean residual across all bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize when items are arriving at the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += 1.0 * (progress - 0.8) * (progress - 0.8);
    }

    score
}
